  now: CovStatus;
  prio: Prio;
  object: string;
  level: 'Platform' | 'Product' | 'Shell' | 'Internal portal' | 'Documentation';
  note?: string;
  turn?: number;
  /** What a later turn added to an item that was already Designed (gaps against the brief closed). */
